import{_ as n,C as i,o as s,c as o,a2 as t,b as l,w as a,a as c,E as d,a3 as p}from"./chunks/framework.CZqXuAiL.js";const A=JSON.parse(`{"title":"Ask Access","description":"Let Pterodactyl users request access to each other's servers — approvals, permission presets, temporary grants, blocking, and a full audit trail.","frontmatter":{"title":"Ask Access","description":"Let Pterodactyl users request access to each other's servers — approvals, permission presets, temporary grants, blocking, and a full audit trail."},"headers":[],"relativePath":"ask-access/index.md","filePath":"ask-access/index.md","lastUpdated":1787470737000}`),h={name:"ask-access/index.md"};function u(g,e,k,m,b,y){const r=i("Mermaid");return s(),o("div",null,[e[1]||(e[1]=t('<h1 id="ask-access" tabindex="-1">Ask Access <a class="header-anchor" href="#ask-access" aria-label="Permalink to &quot;Ask Access&quot;">​</a></h1><p><strong>Server access requests for Pterodactyl Panel</strong> — available as a Blueprint addon or a standalone panel extension. Users can ask for access to another user&#39;s server (by server ID) or to all of someone&#39;s servers (by email), and owners approve, deny, or revoke those requests from a built-in account page.</p><p>Instead of owners manually digging through the Subusers page and guessing which permissions to tick, Ask Access turns the whole flow into a request → approve → manage cycle with sensible permission presets, optional time-limited access, and a complete audit log.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for ALTIS TECH SOLUTIONS by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/Ask-Access" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://xdp.network" target="_blank" rel="noreferrer">Studio</a></p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',6)),(s(),l(p,null,{default:a(()=>[d(r,{id:"mermaid-18",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%5D%0A%20%20%20%20%20%20%20%20UI%5BServer%20Access%20account%20page%5D%20--%3E%20API%5BClient%20API%20%2Fapi%2Fclient%2Fextensions%2Fpterodactylaskaccess%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20SVC%5BAccessRequestService%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20GRANT%5BGrantManagerService%5D%0A%20%20%20%20%20%20%20%20SVC%20--%3E%20SUB%5BSubuserCreationService%20-%20core%5D%0A%20%20%20%20%20%20%20%20GRANT%20--%3E%20SUB%0A%20%20%20%20%20%20%20%20SVC%20--%3E%20DB%5B(askaccess_*%20tables)%5D%0A%20%20%20%20%20%20%20%20GRANT%20--%3E%20DB%0A%20%20%20%20%20%20%20%20CRON%5Bschedule%3Arun%20every%20minute%5D%20--%3E%20PRUNE%5Baskaccess%3Aprune%5D%0A%20%20%20%20%20%20%20%20PRUNE%20--%3E%20GRANT%0A%20%20%20%20end%0A%20%20%20%20GRANT%20--%3E%7Cexpiry%20%2F%20revoke%7C%20DEL%5BDelete%20subuser%20%2B%20RevokeSftpAccessJob%5D%0A%20%20%20%20ADMIN%5BAdmin%20-%20Extensions%20%E2%86%92%20Ask%20Access%5D%20--%3E%20DB%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p>Everything runs <strong>inside the panel</strong> — no node daemons, no external services. Grants are real Pterodactyl subusers, so they work with Wings, SFTP, and the console exactly like manually-added subusers. A scheduled prune command (driven by the panel&#39;s existing <code>schedule:run</code> cron) expires stale requests and revokes temporary access the minute it lapses.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Two ways to ask</strong> — request a single server by its ID/UUID, or request access to <em>all</em> of a user&#39;s servers by email.</li><li><strong>Permission presets</strong> — <code>Read-only</code>, <code>Standard</code>, and <code>Full access</code> map to curated, validated Pterodactyl permission lists. Owners can override the preset per-request before approving. See <a href="./configuration/reference#permission-presets">Configuration</a>.</li><li><strong>Temporary access</strong> — approve access for 1 hour up to 30 days (max 1 year via API). Expiry is automatic: the subuser is removed and SFTP sessions are revoked.</li><li><strong>Active access manager</strong> — an &quot;Active&quot; tab lists everyone with access to your servers across your whole fleet: edit permissions, change duration, add more servers, or remove access in one click.</li><li><strong>Delegated access managers</strong> — grant a trusted subuser the <code>accessmanager.manage</code> permission and they can manage access on that server on your behalf.</li><li><strong>Privacy by design</strong> — email-based requests return an identical response whether or not the account exists, so the feature can&#39;t be used to probe which emails are registered. Owner emails are masked in the requester&#39;s &quot;Sent&quot; list.</li><li><strong>Blocking</strong> — users can block specific accounts; pending requests from a blocked user are auto-denied and future ones are silently dropped.</li><li><strong>Admin policy controls</strong> — panel admins choose who may use the feature (everyone / allowlist / blacklist), set request decay time, and tune rate limits. See <a href="./configuration/reference#admin-panel-settings">Configuration</a>.</li><li><strong>Abuse protection</strong> — per-user creation rate limits, pending-request caps, server-side block throttling, and the panel&#39;s global API rate limiter.</li><li><strong>Full audit trail</strong> — every create/approve/deny/cancel/revoke action is logged with actor, metadata, and IP.</li></ul><hr><h2 id="blueprint-vs-standalone" tabindex="-1">Blueprint vs Standalone <a class="header-anchor" href="#blueprint-vs-standalone" aria-label="Permalink to &quot;Blueprint vs Standalone&quot;">​</a></h2><p>Both packages install the <strong>same</strong> addon — the difference is only how files reach your panel.</p><table tabindex="0"><thead><tr><th></th><th>Blueprint (recommended)</th><th>Standalone</th></tr></thead><tbody><tr><td>Installer</td><td><code>blueprint -install pterodactylaskaccess</code></td><td><code>sudo bash install.sh</code> from the release zip</td></tr><tr><td>Requirement</td><td><a href="https://blueprint.zip" target="_blank" rel="noreferrer">Blueprint</a> framework on the panel</td><td>Plain Pterodactyl panel (Blueprint still needed for the account page route)</td></tr><tr><td>File merging</td><td>Automatic via Blueprint</td><td><code>install.sh</code> copies <code>PanelFiles</code> into place</td></tr><tr><td>Removal</td><td><code>blueprint -remove pterodactylaskaccess</code></td><td><code>sudo bash uninstall.sh</code></td></tr><tr><td>Updates</td><td>Install the new <code>.blueprint</code> package</td><td>Re-run <code>install.sh</code> from the new release</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The account page needs Blueprint&#39;s extends layer</p><p>The <strong>Server Access</strong> page is wired through Blueprint&#39;s <code>resources/scripts/blueprint/extends</code> system. On a panel with no Blueprint at all, the API still works but the page won&#39;t render. For most setups, use the Blueprint package.</p></div><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><p><strong>Blueprint:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylaskaccess-v1.0.0.blueprint</span></span></code></pre></div><p><strong>Standalone:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AskAccess-v1.0.0-standalone.zip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>Then open <strong>Account → Server Access</strong> in the client area. Full walkthrough: <a href="./getting-started/installation">Installation</a></p>`,16))])}const f=n(h,[["render",u]]);export{A as __pageData,f as default};
